441:   function updatePhase() {
442:     if (!decks.a || !decks.b) return;
443:     const a = decks.a, b = decks.b;
444:     const beatsA = a.audio.currentTime * a.bpm / 60;
445:     const beatsB = b.audio.currentTime * b.bpm / 60;
446:     const phaseA = ((beatsA % 1) + 1) % 1;
447:     const phaseB = ((beatsB % 1) + 1) % 1;
448:     let delta = Math.abs(phaseA - phaseB) * 60000 / Math.max(a.bpm, 1);
449:     delta = Math.min(delta, 60000 / Math.max(a.bpm, 1) - delta);
450:     $('#phase-readout').textContent = a.audio.src && b.audio.src ? `FASE ${Math.round(delta)} MS` : 'FASE —';
451:   }
