453:   function measurePhaseDifference(a, b) {
454:     const phaseA = ((a.audio.currentTime * a.bpm / 60) % 1 + 1) % 1;
455:     const phaseB = ((b.audio.currentTime * b.bpm / 60) % 1 + 1) % 1;
456:     const beatFraction = Math.min(Math.abs(phaseA - phaseB), 1 - Math.abs(phaseA - phaseB));
457:     return beatFraction * 60000 / Math.max(1, (a.bpm + b.bpm) / 2);
458:   }
