759:   function handleMidi(event) {
760:     const [status, data1, data2] = event.data;
761:     const command = status & 0xf0;
762:     const channel = status & 0x0f;
763:     const isNote = command === 0x90 && data2 > 0;
764:     const isCC = command === 0xb0;
765:     if (midiLearnEnabled && (isNote || isCC)) {
766:       const target = $('#midi-target-select').value;
767:       midiMap[target] = { type: isNote ? 'note' : 'cc', number: data1, channel };
768:       midiLearnEnabled = false;
769:       midiLearnTarget = null;
770:       persistMidiMap();
771:       updateMidiLearnStatus();
772:       toast(`${MIDI_LABELS[target] || target}: ${midiMessageLabel(midiMap[target])}`);
773:       return;
774:     }
775:     for (const [target, mapping] of Object.entries(midiMap)) {
776:       if (!mapping || mapping.channel !== channel || data1 !== mapping.number) continue;
777:       if (mapping.type === 'note' && isNote) {
778:         if (target.startsWith('play-')) playDeck(target.slice(-1));
779:         else if (target.startsWith('cue-')) cueDeck(target.slice(-1));
780:         else if (target.startsWith('sync-')) syncDeck(target.slice(-1));
781:         else if (target.startsWith('jog-')) nudgeDeck(target.slice(-1), 0.025);
782:       } else if (mapping.type === 'cc' && isCC) {
783:         dispatchMidiControl(target, data2);
784:       }
785:     }
786:   }
