788:   function dispatchMidiControl(target, value) {
789:     if (value > 0 && target.startsWith('play-')) { playDeck(target.slice(-1)); return; }
790:     if (value > 0 && target.startsWith('cue-')) { cueDeck(target.slice(-1)); return; }
791:     if (value > 0 && target.startsWith('sync-')) { syncDeck(target.slice(-1)); return; }
792:     if (target.startsWith('jog-')) {
793:       const delta = value > 64 ? value - 128 : value;
794:       if (delta) nudgeDeck(target.slice(-1), Math.sign(delta) * Math.min(Math.abs(delta), 8) * 0.012);
795:       return;
796:     }
797:     const controls = {
798:       'volume-a': $('[data-volume="a"]'), 'volume-b': $('[data-volume="b"]'),
799:       'pitch-a': $('[data-pitch="a"]'), 'pitch-b': $('[data-pitch="b"]'),
800:       'eq-a-low': $('[data-eq="low"][data-deck="a"]'), 'eq-a-mid': $('[data-eq="mid"][data-deck="a"]'), 'eq-a-high': $('[data-eq="high"][data-deck="a"]'),
801:       'eq-b-low': $('[data-eq="low"][data-deck="b"]'), 'eq-b-mid': $('[data-eq="mid"][data-deck="b"]'), 'eq-b-high': $('[data-eq="high"][data-deck="b"]'),
802:       crossfader: $('#crossfader')
803:     };
804:     const input = controls[target];
805:     if (!input) return;
806:     const min = Number(input.min || 0), max = Number(input.max || 127);
807:     input.value = String(min + (value / 127) * (max - min));
808:     input.dispatchEvent(new Event('input', { bubbles: true }));
809:   }
