184:   function makeDemoWav(bpm, seed) {
185:     const sampleRate = 22050;
186:     const beat = 60 / bpm;
187:     const beatCount = 16;
188:     const length = Math.ceil(sampleRate * beat * beatCount);
189:     const samples = new Float32Array(length);
190:     let state = seed >>> 0;
191:     const random = () => { state = (state * 1664525 + 1013904223) >>> 0; return state / 4294967296; };
192:     for (let b = 0; b < beatCount; b++) {
193:       const start = Math.floor(b * beat * sampleRate);
194:       const kickLength = Math.floor(sampleRate * 0.24);
195:       for (let i = 0; i < kickLength && start + i < length; i++) {
196:         const t = i / sampleRate;
197:         const env = Math.exp(-t * 17);
198:         const freq = 43 + 75 * Math.exp(-t * 28);
199:         samples[start + i] += Math.sin(2 * Math.PI * freq * t) * env * 0.78;
200:       }
201:       if (b % 4 === 1 || b % 4 === 3) {
202:         const clapStart = start + Math.floor(sampleRate * beat * 0.12);
203:         for (let i = 0; i < sampleRate * 0.15 && clapStart + i < length; i++) {
204:           const t = i / sampleRate;
205:           samples[clapStart + i] += (random() * 2 - 1) * Math.exp(-t * 24) * 0.17;
206:         }
207:       }
208:       const hatStart = start + Math.floor(sampleRate * beat * 0.5);
209:       for (let i = 0; i < sampleRate * 0.045 && hatStart + i < length; i++) {
210:         const t = i / sampleRate;
211:         samples[hatStart + i] += (random() * 2 - 1) * Math.exp(-t * 75) * 0.08;
212:       }
213:     }
214:     const buffer = new ArrayBuffer(44 + samples.length * 2);
215:     const view = new DataView(buffer);
216:     const write = (offset, text) => [...text].forEach((char, index) => view.setUint8(offset + index, char.charCodeAt(0)));
217:     write(0, 'RIFF'); view.setUint32(4, 36 + samples.length * 2, true); write(8, 'WAVE');
218:     write(12, 'fmt '); view.setUint32(16, 16, true); view.setUint16(20, 1, true);
219:     view.setUint16(22, 1, true); view.setUint32(24, sampleRate, true); view.setUint32(28, sampleRate * 2, true);
220:     view.setUint16(32, 2, true); view.setUint16(34, 16, true); write(36, 'data');
221:     view.setUint32(40, samples.length * 2, true);
222:     for (let i = 0; i < samples.length; i++) view.setInt16(44 + i * 2, Math.max(-1, Math.min(1, samples[i])) * 32767, true);
223:     return new Blob([buffer], { type: 'audio/wav' });
224:   }
